/**
 * @fileoverview The place table is generated by core/scripts/geo, never
 * written by hand: every file its manifest names has the SHA-256 the
 * generator wrote, so an edit by hand fails here and a change to the data is
 * a run of the generator.
 */

import { createHash } from 'node:crypto';
import { readFileSync } from 'node:fs';
import { join } from 'node:path';
import { expect, test } from 'vite-plus/test';

const DATA = join(import.meta.dirname, '../../src/place/data');

interface Manifest {
  source: { commit: string; layers: Record<string, string>; icu: string };
  hashes: Record<string, string>;
}

const manifest = JSON.parse(
  readFileSync(join(DATA, 'manifest.json'), 'utf8'),
) as Manifest;

test('the manifest names the place table', () => {
  expect(Object.keys(manifest.hashes)).toContain('places.json');
});

test('every file the manifest names is as the generator wrote it', () => {
  for (const [name, hash] of Object.entries(manifest.hashes)) {
    const bytes = readFileSync(join(DATA, name));
    expect(createHash('sha256').update(bytes).digest('hex'), name).toBe(hash);
  }
});
